  destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  clear SPAL AF2 AF3 EB5 PB5 APE EAL; hydeL DPE; hydeL PAL; hydeL IAL;
  unfold P_A_BP_PARSE_START_LINE, P_A_BP_PARSE_FIELDS, P_A_BP_INNER_PARSE_START_LINE, P_A_BP_INNER_PARSE_FIELDS, APSL_RET, APF_RET,
