    pose proof (aconst_transport_awin _ _ mc AC MU WM FW) as ACf;
    pose proof (stack0_transport _ _ _ _ _ SK MU WM ltac:(eapply Forall_impl; [| exact FW]; intros ?iv ?HW; exact (proj1 (proj2 HW)))) as SKf;
    finish; [ exact FRlo
